command:
set -euo pipefail
git log --no-merges --format='@@@%H%x09%ad%x09%s' --date=short --name-only d33c62eebc48de5e8a65c50e057addf25f125c6b..51e7faddad943ab7727e407d008e474ec076566d |
awk '
function flush(  n,k,list) {
  if (!seen) return;
  n=0; list="";
  for (k in roots) {n++; list=list (list?",":"") k}
  if (n >= 5) printf "%d\t%s\t%s\t%s\t%s\n", n, hash, date, subject, list;
}
function clear_roots( k){for(k in roots) delete roots[k]}
$0 ~ /^@@@/ {flush(); clear_roots(); seen=1; line=substr($0,4); split(line,a,"\t"); hash=a[1]; date=a[2]; subject=a[3]; next}
NF == 0 {next}
{split($0,p,"/"); root=p[1]; if (root ~ /^(src|tests|docs|tasks|tools|cmake|methods|benchmarks|assets|ara|\.github)$/) roots[root]=1}
END {flush()}' | sort -nr -k1,1

